CREATE DATABASE IF NOT EXISTS fasobusiness CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE fasobusiness;
CREATE TABLE companies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,sector VARCHAR(100) DEFAULT 'Autre',phone VARCHAR(40),address VARCHAR(255),city VARCHAR(100),ifu VARCHAR(80),created_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NULL,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('owner','manager','cashier','superadmin') NOT NULL DEFAULT 'owner',status ENUM('active','suspended') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,sku VARCHAR(80),name VARCHAR(180) NOT NULL,category VARCHAR(100),buy_price DECIMAL(14,2) NOT NULL DEFAULT 0,sell_price DECIMAL(14,2) NOT NULL DEFAULT 0,stock INT NOT NULL DEFAULT 0,alert_stock INT NOT NULL DEFAULT 5,created_at DATETIME NOT NULL,INDEX(company_id),UNIQUE KEY uq_sku_company(company_id,sku),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE customers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,phone VARCHAR(40),email VARCHAR(190),address VARCHAR(255),created_at DATETIME NOT NULL,INDEX(company_id),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE sales(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NULL,invoice_no VARCHAR(60) NOT NULL,total DECIMAL(14,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'paid',payment_method VARCHAR(40) DEFAULT 'cash',created_at DATETIME NOT NULL,INDEX(company_id),UNIQUE KEY uq_invoice_company(company_id,invoice_no),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE sale_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sale_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,product_name VARCHAR(180) NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(14,2) NOT NULL,line_total DECIMAL(14,2) NOT NULL,FOREIGN KEY(sale_id) REFERENCES sales(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE expenses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,label VARCHAR(180) NOT NULL,category VARCHAR(100),amount DECIMAL(14,2) NOT NULL,expense_date DATE NOT NULL,note TEXT,INDEX(company_id),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE) ENGINE=InnoDB;
